from dataclasses import dataclass
from typing import Optional

@dataclass
class DiffLine:
    line_number: int
    content: str
    type: str  # 'added', 'removed', 'context'

@dataclass
class FileDiff:
    filename: str
    status: str  # 'added', 'modified', 'removed', 'renamed'
    additions: int
    deletions: int
    patch: Optional[str]
    lines: list[DiffLine]
    language: str

def parse_patch(patch: str) -> list[DiffLine]:
    """GitHub unified diff patch'ini parse et."""
    if not patch:
        return []

    lines = []
    current_line = 0

    for raw_line in patch.split('\n'):
        if raw_line.startswith('@@'):
            # @@ -old_start,old_count +new_start,new_count @@
            parts = raw_line.split('+')
            if len(parts) > 1:
                current_line = int(parts[1].split(',')[0]) - 1
            continue

        current_line += 1

        if raw_line.startswith('+'):
            lines.append(DiffLine(current_line, raw_line[1:], 'added'))
        elif raw_line.startswith('-'):
            lines.append(DiffLine(current_line, raw_line[1:], 'removed'))
        else:
            lines.append(DiffLine(current_line, raw_line, 'context'))

    return lines

def detect_language(filename: str) -> str:
    """Dosya uzantısından programlama dilini tespit et."""
    ext_map = {
        '.py': 'python', '.js': 'javascript', '.ts': 'typescript',
        '.tsx': 'typescript', '.jsx': 'javascript', '.java': 'java',
        '.go': 'go', '.rs': 'rust', '.rb': 'ruby', '.php': 'php',
        '.cs': 'csharp', '.cpp': 'cpp', '.c': 'c', '.swift': 'swift',
    }
    for ext, lang in ext_map.items():
        if filename.endswith(ext):
            return lang
    return 'unknown'

def parse_pr_files(files: list[dict]) -> list[FileDiff]:
    """GitHub API yanıtındaki dosyaları FileDiff listesine dönüştür."""
    diffs = []
    for f in files:
        language = detect_language(f['filename'])
        lines = parse_patch(f.get('patch', ''))
        diffs.append(FileDiff(
            filename=f['filename'],
            status=f['status'],
            additions=f['additions'],
            deletions=f['deletions'],
            patch=f.get('patch'),
            lines=lines,
            language=language,
        ))
    return diffs

