import ast
import re
from dataclasses import dataclass
from typing import Optional

@dataclass
class CodeSmell:
    name: str
    severity: str  # 'warning', 'suggestion'
    line: int
    message: str
    suggestion: str

def detect_patterns(code: str, filename: str) -> list[CodeSmell]:
    """Bilinen anti-pattern ve code smell'leri tespit et."""
    smells = []
    lines = code.splitlines()

    try:
        tree = ast.parse(code)
    except SyntaxError:
        return smells

    # 1. Long function (50+ satır)
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            length = (node.end_lineno or node.lineno) - node.lineno
            if length > 50:
                smells.append(CodeSmell(
                    'long_function', 'warning', node.lineno,
                    f"'{node.name}' fonksiyonu {length} satır — 50 satırdan uzun",
                    "Fonksiyonu daha küçük, tek sorumluluğa sahip fonksiyonlara böl."
                ))

            # 2. Too many parameters (5+)
            param_count = len(node.args.args)
            if param_count > 5:
                smells.append(CodeSmell(
                    'too_many_params', 'warning', node.lineno,
                    f"'{node.name}' fonksiyonu {param_count} parametre alıyor",
                    "Parametreleri bir dataclass veya dict ile grupla."
                ))

    # 3. Deep nesting (4+ level)
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            depth = _max_nesting(node)
            if depth >= 4:
                smells.append(CodeSmell(
                    'deep_nesting', 'warning', node.lineno,
                    f"'{node.name}' içinde {depth} seviye iç içe geçme",
                    "Early return pattern veya guard clause kullan."
                ))

    # 4. Magic numbers
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            if node.value not in (0, 1, -1, 2, 100, True, False, None):
                if hasattr(node, 'lineno'):
                    smells.append(CodeSmell(
                        'magic_number', 'suggestion', node.lineno,
                        f"Satır {node.lineno}'de magic number: {node.value}",
                        "Anlamlı bir sabit (const) olarak tanımla."
                    ))

    # 5. TODO/FIXME/HACK yorumları
    for i, line in enumerate(lines, 1):
        if re.search(r'#\s*(TODO|FIXME|HACK|XXX)', line, re.IGNORECASE):
            smells.append(CodeSmell(
                'todo_comment', 'suggestion', i,
                f"Satır {i}'de çözülmemiş TODO/FIXME yorumu",
                "Teknik borcu takip et ve sprint planlamasına ekle."
            ))

    return smells

def _max_nesting(node: ast.AST, depth: int = 0) -> int:
    max_d = depth
    nesting = (ast.If, ast.For, ast.While, ast.With, ast.Try)
    for child in ast.iter_child_nodes(node):
        if isinstance(child, nesting):
            max_d = max(max_d, _max_nesting(child, depth + 1))
        else:
            max_d = max(max_d, _max_nesting(child, depth))
    return max_d

