from dataclasses import dataclass

@dataclass
class ConfidenceResult:
    score: float  # 0.0 - 1.0
    factors: dict
    recommendation: str

def calculate_confidence(issue: dict, file_context: dict) -> ConfidenceResult:
    """Review issue'nun güvenilirlik skorunu hesapla."""
    factors = {}
    score = 0.5  # başlangıç

    # 1. Severity tutarlılığı
    if issue.get('severity') in ('critical', 'warning'):
        if issue.get('code_fix'):
            score += 0.15
            factors['has_fix'] = True
        else:
            score -= 0.1
            factors['has_fix'] = False

    # 2. Satır numarası doğruluğu
    if issue.get('line') and issue['line'] > 0:
        score += 0.1
        factors['has_line'] = True

    # 3. Kategori spesifikliği
    valid_categories = {'security', 'performance', 'readability', 'logic', 'style', 'best_practice'}
    if issue.get('category') in valid_categories:
        score += 0.1
        factors['valid_category'] = True

    # 4. Claude confidence (varsa)
    claude_conf = issue.get('confidence', 0.5)
    score = score * 0.6 + claude_conf * 0.4

    score = max(0.0, min(1.0, score))

    if score >= 0.8:
        recommendation = 'high_confidence'
    elif score >= 0.5:
        recommendation = 'medium_confidence'
    else:
        recommendation = 'low_confidence'

    return ConfidenceResult(round(score, 2), factors, recommendation)

