import httpx

class GitHubCommentService:
    BASE_URL = "https://api.github.com"

    def __init__(self, access_token: str):
        self.client = httpx.AsyncClient(
            base_url=self.BASE_URL,
            headers={
                "Authorization": f"Bearer {access_token}",
                "Accept": "application/vnd.github.v3+json",
            },
            timeout=30.0,
        )

    async def create_review(
        self,
        owner: str,
        repo: str,
        pr_number: int,
        review_result: dict,
    ) -> dict:
        """PR'a review yorumları gönder."""
        comments = []
        for issue in review_result.get('issues', []):
            if issue.get('line') and issue.get('severity') != 'praise':
                emoji = self._severity_emoji(issue['severity'])
                body = f"{emoji} **{issue['severity'].upper()}** ({issue.get('category', 'general')})\n\n"
                body += f"{issue['message']}\n\n"
                if issue.get('suggestion'):
                    body += f"💡 **Öneri:** {issue['suggestion']}\n\n"
                if issue.get('code_fix'):
                    body += f"```suggestion\n{issue['code_fix']}\n```\n"
                if issue.get('confidence_score'):
                    body += f"\n_Güven: {issue['confidence_score']:.0%}_"

                comments.append({
                    'path': issue.get('file', ''),
                    'line': issue['line'],
                    'body': body,
                })

        # Summary comment
        summary = self._build_summary(review_result)

        response = await self.client.post(
            f"/repos/{owner}/{repo}/pulls/{pr_number}/reviews",
            json={
                'body': summary,
                'event': 'COMMENT',
                'comments': comments[:50],  # GitHub max 50 comment per review
            },
        )
        response.raise_for_status()
        return response.json()

    def _severity_emoji(self, severity: str) -> str:
        return {'critical': '🔴', 'warning': '🟡', 'suggestion': '🔵', 'praise': '🟢'}.get(severity, '⚪')

    def _build_summary(self, result: dict) -> str:
        score = result.get('average_score', 0)
        total = result.get('total_issues', 0)
        files = result.get('files_reviewed', 0)
        return (
            f"## 🤖 AI Code Review\n\n"
            f"**Skor:** {score}/100 | "
            f"**Dosya:** {files} | "
            f"**Bulgu:** {total}\n\n"
            f"{'✅ Kod kalitesi iyi!' if score >= 80 else '⚠️ İyileştirme önerileri var.'}\n\n"
            f"_Bu review AI tarafından oluşturulmuştur. Yanlış bulgu için 👎 butonunu kullanın._"
        )

    async def close(self):
        await self.client.aclose()

from datetime import datetime

def generate_security_report(scan_result: dict, repo_name: str, pr_number: int) -> dict:
    """Güvenlik taraması sonuçlarını yapılandırılmış rapor formatına dönüştür."""
    findings = scan_result.get('findings', [])

    # Severity'ye göre sırala (critical > high > medium > low)
    severity_order = {'critical': 0, 'high': 1, 'medium': 2, 'low': 3}
    sorted_findings = sorted(findings, key=lambda f: severity_order.get(f.get('severity', 'low'), 4))

    # OWASP kategorilerine göre grupla
    by_category = {}
    for f in sorted_findings:
        cat = f.get('owasp_category', 'Other')
        if cat not in by_category:
            by_category[cat] = []
        by_category[cat].append(f)

    return {
        'report_date': datetime.utcnow().isoformat(),
        'repo': repo_name,
        'pr_number': pr_number,
        'summary': {
            'total': len(findings),
            'critical': scan_result.get('critical', 0),
            'high': scan_result.get('high', 0),
            'pass': scan_result.get('critical', 0) == 0,
        },
        'findings_by_severity': sorted_findings,
        'findings_by_category': by_category,
        'recommendations': _generate_recommendations(scan_result),
    }

def _generate_recommendations(result: dict) -> list[str]:
    recs = []
    if result.get('critical', 0) > 0:
        recs.append('ACIL: Kritik güvenlik açıkları bulundu. PR merge edilmeden düzeltilmeli.')
    if result.get('high', 0) > 0:
        recs.append('ÖNEMLİ: Yüksek seviye güvenlik sorunları mevcut. 3 gün içinde düzeltilmeli.')
    if not recs:
        recs.append('Güvenlik taraması başarılı. Kritik veya yüksek seviye bulgu yok.')
    return recs

