      <ReactDiffViewer
        oldValue={oldCode}
        newValue={newCode}
        splitView={true}
        compareMethod={DiffMethod.WORDS}
        useDarkTheme={true}
        styles={{
          variables: {
            dark: {
              diffViewerBackground: '#1a1a2e',
              addedBackground: '#0d3320',
              removedBackground: '#3d1f1f',
              wordAddedBackground: '#1a6b3a',
              wordRemovedBackground: '#6b1a1a',
            },
          },
