from dataclasses import dataclass, field
from typing import Optional, Callable
import re

@dataclass
class Rule:
    id: str
    name: str
    category: str  # 'complexity', 'naming', 'security', 'style'
    severity: str  # 'error', 'warning', 'suggestion'
    enabled: bool = True
    config: dict = field(default_factory=dict)
    custom_pattern: Optional[str] = None

DEFAULT_RULES = [
    Rule('max-complexity', 'Maksimum Cyclomatic Complexity', 'complexity', 'warning', config={'threshold': 15}),
    Rule('max-function-length', 'Maksimum Fonksiyon Uzunluğu', 'complexity', 'warning', config={'threshold': 50}),
    Rule('max-params', 'Maksimum Parametre Sayısı', 'complexity', 'warning', config={'threshold': 5}),
    Rule('max-nesting', 'Maksimum Nesting Derinliği', 'complexity', 'warning', config={'threshold': 4}),
    Rule('no-magic-numbers', 'Magic Number Kullanımı', 'style', 'suggestion', config={'whitelist': [0, 1, -1, 2, 100]}),
    Rule('no-todo-comments', 'TODO/FIXME Yorumları', 'style', 'suggestion'),
    Rule('sql-injection', 'SQL Injection Kontrolü', 'security', 'error'),
    Rule('hardcoded-secrets', 'Hardcoded Secret Kontrolü', 'security', 'error'),
    Rule('no-eval', 'eval/exec Kullanımı', 'security', 'error'),
]

class RuleEngine:
    def __init__(self, rules: list[Rule] = None):
        self.rules = {r.id: r for r in (rules or DEFAULT_RULES)}

    def apply_overrides(self, overrides: dict):
        """Konfigürasyon dosyasından gelen override'ları uygula."""
        for rule_id, config in overrides.items():
            if rule_id in self.rules:
                rule = self.rules[rule_id]
                if 'enabled' in config:
                    rule.enabled = config['enabled']
                if 'severity' in config:
                    rule.severity = config['severity']
                if 'config' in config:
                    rule.config.update(config['config'])

    def get_enabled_rules(self) -> list[Rule]:
        return [r for r in self.rules.values() if r.enabled]

    def add_custom_rule(self, rule_id: str, name: str, pattern: str, severity: str = 'warning'):
        self.rules[rule_id] = Rule(
            id=rule_id, name=name, category='custom',
            severity=severity, custom_pattern=pattern,
        )

    def check_custom_rules(self, code: str) -> list[dict]:
        findings = []
        for rule in self.rules.values():
            if rule.enabled and rule.custom_pattern:
                for i, line in enumerate(code.splitlines(), 1):
                    if re.search(rule.custom_pattern, line):
                        findings.append({
                            'rule_id': rule.id,
                            'line': i,
                            'severity': rule.severity,
                            'message': rule.name,
                        })
        return findings

import yaml
from typing import Optional
from analysis.rules.rule_engine import RuleEngine

DEFAULT_CONFIG = {
    'ignore_paths': ['test/', 'tests/', 'migrations/', '__pycache__/', 'node_modules/'],
    'max_complexity': 15,
    'max_function_length': 50,
    'max_params': 5,
    'max_nesting': 4,
    'required_test_coverage': 0,
    'severity_overrides': {},
    'custom_rules': [],
    'language_specific': {},
    'enabled_categories': ['complexity', 'security', 'style', 'naming'],
}

def parse_config(yaml_content: str) -> dict:
    """Repo'daki .codereview.yml dosyasını parse et."""
    try:
        config = yaml.safe_load(yaml_content) or {}
    except yaml.YAMLError:
        return DEFAULT_CONFIG.copy()

    # Default ile merge et
    merged = DEFAULT_CONFIG.copy()
    merged.update(config)
    return merged

def apply_config_to_engine(config: dict, engine: RuleEngine):
    """Konfigürasyonu rule engine'e uygula."""
    # Threshold override'ları
    if 'max_complexity' in config:
        engine.apply_overrides({'max-complexity': {'config': {'threshold': config['max_complexity']}}})
    if 'max_function_length' in config:
        engine.apply_overrides({'max-function-length': {'config': {'threshold': config['max_function_length']}}})

    # Severity override'ları
    for rule_id, severity in config.get('severity_overrides', {}).items():
        engine.apply_overrides({rule_id: {'severity': severity}})

    # Custom rules
    for rule in config.get('custom_rules', []):
        engine.add_custom_rule(
            rule_id=rule.get('id', f"custom-{rule.get('name', 'unnamed')}"),
            name=rule.get('name', 'Custom Rule'),
            pattern=rule.get('pattern', ''),
            severity=rule.get('severity', 'warning'),
        )

def should_skip_file(filename: str, config: dict) -> bool:
    """Dosyanın analiz dışında tutulup tutulmayacağını kontrol et."""
    for path in config.get('ignore_paths', []):
        if path in filename:
            return True
    return False

async def get_config_file(self, owner: str, repo: str, branch: str = 'main') -> Optional[str]:
    """Repo'daki .codereview.yml dosyasını oku."""
    try:
        response = await self.client.get(
            f"/repos/{owner}/{repo}/contents/.codereview.yml",
            params={'ref': branch},
        )
        if response.status_code == 200:
            import base64
            content = response.json().get('content', '')
            return base64.b64decode(content).decode('utf-8')
    except Exception:
        pass
    return None

import httpx

class StatusCheckService:
    BASE_URL = "https://api.github.com"

    def __init__(self, access_token: str):
        self.client = httpx.AsyncClient(
            base_url=self.BASE_URL,
            headers={
                "Authorization": f"Bearer {access_token}",
                "Accept": "application/vnd.github.v3+json",
            },
        )

    async def create_check_run(
        self, owner: str, repo: str, head_sha: str,
        score: float, issues_count: int, critical_count: int,
        threshold: int = 70,
    ) -> dict:
        """GitHub Check Run oluştur — PR'da status göster."""
        passed = score >= threshold and critical_count == 0

        response = await self.client.post(
            f"/repos/{owner}/{repo}/check-runs",
            json={
                'name': 'AI Code Review',
                'head_sha': head_sha,
                'status': 'completed',
                'conclusion': 'success' if passed else 'failure',
                'output': {
                    'title': f"Skor: {score}/100 — {'Geçti ✅' if passed else 'Kaldı ❌'}",
                    'summary': (
                        f"**Kod Kalitesi:** {score}/100\n"
                        f"**Toplam Bulgu:** {issues_count}\n"
                        f"**Kritik:** {critical_count}\n\n"
                        f"{'PR merge için hazır.' if passed else f'Minimum skor: {threshold}. Kritik sorunları düzeltin.'}"
                    ),
                },
            },
        )
        response.raise_for_status()
        return response.json()

    async def close(self):
        await self.client.aclose()

import httpx
from datetime import datetime

class AutoMergeService:
    def __init__(self, access_token: str):
        self.client = httpx.AsyncClient(
            base_url="https://api.github.com",
            headers={"Authorization": f"Bearer {access_token}", "Accept": "application/vnd.github.v3+json"},
        )

    async def evaluate_auto_merge(
        self, owner: str, repo: str, pr_number: int,
        review_score: float, critical_count: int,
        config: dict,
    ) -> dict:
        """Auto-merge kriterlerini değerlendir."""
        auto_merge_config = config.get('auto_merge', {})
        if not auto_merge_config.get('enabled', False):
            return {'eligible': False, 'reason': 'Auto-merge devre dışı'}

        min_score = auto_merge_config.get('min_score', 90)
        require_no_critical = auto_merge_config.get('require_no_critical', True)

        if critical_count > 0 and require_no_critical:
            return {'eligible': False, 'reason': f'{critical_count} kritik bulgu mevcut'}

        if review_score < min_score:
            return {'eligible': False, 'reason': f'Skor {review_score} < minimum {min_score}'}

        # Tüm status check'ler geçmiş mi?
        pr_info = await self.client.get(f"/repos/{owner}/{repo}/pulls/{pr_number}")
        pr_data = pr_info.json()
        if not pr_data.get('mergeable', False):
            return {'eligible': False, 'reason': 'PR merge çakışması var'}

        return {
            'eligible': True,
            'score': review_score,
            'auto_merged_at': datetime.utcnow().isoformat(),
        }

    async def merge_pr(self, owner: str, repo: str, pr_number: int) -> dict:
        response = await self.client.put(
            f"/repos/{owner}/{repo}/pulls/{pr_number}/merge",
            json={'merge_method': 'squash'},
        )
        response.raise_for_status()
        return response.json()

    async def close(self):
        await self.client.aclose()

