import json
import hashlib
from redis import asyncio as aioredis
from app.core.config import settings

class CacheService:
    def __init__(self):
        self.redis = aioredis.from_url(settings.REDIS_URL)

    async def get_cached_review(self, file_hash: str) -> dict | None:
        """Daha önce analiz edilmiş dosyanın cache'lenmiş sonucunu döndür."""
        cached = await self.redis.get(f"review:{file_hash}")
        if cached:
            return json.loads(cached)
        return None

    async def cache_review(self, file_hash: str, result: dict, ttl: int = 3600):
        """Review sonucunu 1 saat cache'le."""
        await self.redis.set(f"review:{file_hash}", json.dumps(result), ex=ttl)

    @staticmethod
    def hash_content(content: str) -> str:
        return hashlib.sha256(content.encode()).hexdigest()

    async def invalidate(self, file_hash: str):
        await self.redis.delete(f"review:{file_hash}")

    async def close(self):
        await self.redis.close()
